<script setup lang="ts">
import { computed } from 'vue'
import { editingText, type InputDefinition, type InputControl } from './inputs'
const props = defineProps<{ input: InputDefinition; control: InputControl; prefix: string }>()
const numeric = computed(() => ['number', 'integer'].includes(props.input.type))
const choice = computed(() => ['select', 'segmented', 'radio'].includes(props.control.style || ''))
function numericField(key: string, event: Event) { const value = (event.target as HTMLInputElement).value; if (!value.trim()) delete props.control[key]; else props.control[key] = Number(value) }
function optionValue(index: number, value: string) { const option = props.control.options?.[index]; if (option) option.value_json = props.input.type === 'string' ? JSON.stringify(value) : value }
</script>
<template>
  <div class="control-settings">
    <label :for="prefix + '-style'">Control</label><select :id="prefix + '-style'" :aria-label="`${prefix} control`" v-model="control.style"><option value="automatic">Automatic</option><template v-if="numeric"><option value="number">Number field</option><option value="slider">Slider</option><option value="stepper">Stepper</option></template><option v-if="input.type === 'string'" value="json">Config Editor</option><template v-if="input.type === 'string' || input.type === 'integer'"><option value="select">Select</option><option value="segmented">Segmented</option><option value="radio">Radio</option></template><template v-if="input.type === 'range'"><option value="slider">Range slider · shared bounds</option><option value="range_sliders">Two sliders · separate bounds</option></template></select>
    <div v-if="input.type === 'range' && ['slider', 'range_sliders'].includes(control.style || '')" class="input-definition-grid"><label v-for="field in control.style === 'range_sliders' ? ['start_minimum', 'start_maximum', 'finish_minimum', 'finish_maximum', 'step'] : ['minimum', 'maximum', 'step']" :key="field">{{ field.replaceAll('_', ' ') }}<input type="number" :aria-label="`${prefix} ${field.replaceAll('_', ' ')}`" :value="control[field]" @input="numericField(field, $event)"></label></div>
    <template v-if="numeric && !choice"><div class="input-definition-grid"><label>Minimum<input type="number" :aria-label="`${prefix} minimum`" :value="control.minimum" @input="numericField('minimum', $event)"></label><label>Maximum<input type="number" :aria-label="`${prefix} maximum`" :value="control.maximum" @input="numericField('maximum', $event)"></label><label>Step<input type="number" :aria-label="`${prefix} step`" :value="control.step" @input="numericField('step', $event)"></label><label>Unit<input v-model="control.unit" :aria-label="`${prefix} unit`" maxlength="256"></label></div></template>
    <template v-if="control.style === 'json'"><label>Config format<select v-model="control.config_format" :aria-label="`${prefix} config format`"><option value="json">JSON</option><option value="yaml">YAML</option><option value="toml">TOML</option></select></label></template>
    <template v-if="choice"><p class="source-note">Options</p><div v-for="(option, index) in control.options || []" :key="index" class="control-option"><input v-model="option.label" :aria-label="`${prefix} option ${index + 1} label`" placeholder="Label" maxlength="256"><input :value="editingText(option.value_json, input.type)" :aria-label="`${prefix} option ${index + 1} value`" placeholder="Value" @input="optionValue(index, ($event.target as HTMLInputElement).value)"><button type="button" :aria-label="`Delete ${prefix} option ${index + 1}`" @click="control.options?.splice(index, 1)">×</button></div><button type="button" @click="(control.options ||= []).push({ label: 'Option ' + ((control.options?.length || 0) + 1), value_json: input.type === 'integer' ? String((control.options?.length || 0) + 1) : JSON.stringify('Option ' + ((control.options?.length || 0) + 1)) })">Add option</button></template>
  </div>
</template>
